"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Firefly Slider: a thin warm track whose filled range wears the primary
 * button's lit material. Each thumb is a lit knob of the same material that
 * grows a little under the pointer and while dragged. Pass an array value
 * for a range; the slider renders one thumb per value.
 */
const Slider = React.forwardRef<
  HTMLDivElement,
  WithClassName<SliderPrimitive.Root.Props>
>(({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
  const _values = Array.isArray(value)
    ? value
    : Array.isArray(defaultValue)
      ? defaultValue
      : [min];

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      ref={ref}
      thumbAlignment="edge"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn(
        "relative w-full data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SliderPrimitive.Control className="relative flex h-6 w-full touch-none select-none items-center">
        <SliderPrimitive.Track
          data-slot="slider-track"
          className="relative h-1.5 w-full grow overflow-hidden rounded-full bg-(--surface-3)"
        >
          <SliderPrimitive.Indicator
            data-slot="slider-range"
            className="rounded-full bg-primary bg-(image:--gradient-primary) shadow-(--shadow-control)"
          />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            className={cn(
              "block size-5 shrink-0 cursor-grab rounded-full bg-primary bg-(image:--gradient-primary) shadow-(--shadow-control)",
              "transition-[scale] duration-fast ease-out hover:scale-105 active:cursor-grabbing active:scale-110 data-[dragging]:scale-110",
              "has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-ring",
              "data-[disabled]:pointer-events-none",
            )}
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  );
});
Slider.displayName = "Slider";

export { Slider };
